290	void ref_attn(const std::vector<__nv_bfloat16>& q, int B, int H, int S, int D,
291	              const std::vector<__nv_bfloat16>& k, int KV, const std::vector<__nv_bfloat16>& v,
292	              bool causal, std::vector<__nv_bfloat16>& out) {
293	    out.assign(B * H * S * D, __float2bfloat16(0.f));
294	    float scale = 1.0f / sqrtf((float)D);
295	    int hpk = H / KV;
296	    for (int b = 0; b < B; ++b) for (int h = 0; h < H; ++h) {
297	        int kh = h / hpk;
298	        for (int s = 0; s < S; ++s) {
299	            float maxv = -INFINITY;
300	            for (int t = 0; t < S; ++t) {
301	                if (causal && t > s) break;
302	                float acc = 0;
303	                for (int d = 0; d < D; ++d)
304	                    acc += __bfloat162float(q[((long long)b*H+h)*S*D + s*D + d]) *
305	                           __bfloat162float(k[((long long)b*KV+kh)*S*D + t*D + d]);
306	                acc *= scale;
307	                if (causal && t > s) break;
308	                maxv = fmaxf(maxv, acc);
309	            }
310	            float sum = 0;
311	            std::vector<float> p(S);
312	            for (int t = 0; t < S; ++t) {
313	                if (causal && t > s) break;
314	                float acc = 0;
315	                for (int d = 0; d < D; ++d)
316	                    acc += __bfloat162float(q[((long long)b*H+h)*S*D + s*D + d]) *
317	                           __bfloat162float(k[((long long)b*KV+kh)*S*D + t*D + d]);
318	                acc *= scale;
319	                if (causal && t > s) break;
320	                p[t] = expf(acc - maxv);
321	                sum += p[t];
322	            }
323	            for (int d = 0; d < D; ++d) {
324	                float acc = 0;
325	                for (int t = 0; t < S; ++t) {
326	                    if (causal && t > s) break;
327	                    acc += p[t] * __bfloat162float(v[((long long)b*KV+kh)*S*D + t*D + d]);
328	                }
329	                out[((long long)b*H+h)*S*D + s*D + d] = __float2bfloat16(acc / sum);
330	            }
331	        }
332	    }
333	}
