            for (int j = 0; j < 8; ++j) s_frag.x[j] *= scale;
            if (warp == 0 && dbgS) {
#pragma unroll
                for (int j = 0; j < 8; ++j) {
                    const int rr = ((j & 2) ? 8 : 0) + lane / 4;
                    const int cc = 2 * (lane % 4) + (j & 1) + ((j & 4) ? 8 : 0);
                    dbgS[rr * 64 + 16 * i + cc] = s_frag.x[j];
                }
            }
            if (may_mask) {
#pragma unroll
                for (int j = 0; j < 8; ++j) {
                    const int rr = ((j & 2) ? 8 : 0) + lane / 4;
                    const int cc = 2 * (lane % 4) + (j & 1) + ((j & 4) ? 8 : 0);
                    if (kvc + cc > m0 + rr) s_frag.x[j] = -INFINITY;
                }
            }
